import{_ as t,c as a,o as e,ag as l}from"./chunks/framework.ymCRTBvy.js";const c=JSON.parse('{"title":"📘 《iOS 18 UIKit纯代码与MVVM实战精解》","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_mvvm/index.md","filePath":"uikit/uikit_mvvm/index.md"}'),o={name:"uikit/uikit_mvvm/index.md"};function r(n,i,d,s,_,u){return e(),a("div",null,i[0]||(i[0]=[l('<h1 id="📘-《ios-18-uikit纯代码与mvvm实战精解》" tabindex="-1">📘 《iOS 18 UIKit纯代码与MVVM实战精解》 <a class="header-anchor" href="#📘-《ios-18-uikit纯代码与mvvm实战精解》" aria-label="Permalink to &quot;📘 《iOS 18 UIKit纯代码与MVVM实战精解》&quot;">​</a></h1><h2 id="📖-内容简介" tabindex="-1">📖 内容简介： <a class="header-anchor" href="#📖-内容简介" aria-label="Permalink to &quot;📖 内容简介：&quot;">​</a></h2><p>本书是一本面向中高级iOS开发者的实战指南，全面讲解在iOS 18环境下使用纯代码方式构建UIKit应用，并结合MVVM架构模式进行项目开发的全流程。全书从项目初始化、界面构建、布局系统，到设计模式、数据绑定、测试优化，系统覆盖了现代iOS开发中的核心技术与最佳实践。</p><p>本书不仅深入讲解了UIKit各组件的代码创建与布局方式，还重点介绍了MVVM模式在iOS开发中的实际应用，包括ViewModel的设计、数据绑定机制、依赖注入、Coordinator导航模式等高级主题。通过大量可落地的代码示例和项目场景，帮助开发者构建出结构清晰、易于测试和维护的高质量应用。</p><h2 id="✅-你将学到" tabindex="-1">✅ 你将学到： <a class="header-anchor" href="#✅-你将学到" aria-label="Permalink to &quot;✅ 你将学到：&quot;">​</a></h2><ul><li>掌握纯代码构建iOS用户界面能力</li><li>精通UIKit组件的创建与布局</li><li>熟练使用Auto Layout进行动态约束</li><li>实现导航控制器和标签栏控制器</li><li>高效构建和管理列表与集合视图</li><li>深入理解并应用MVVM设计模式</li><li>掌握数据绑定技术实现视图与逻辑分离</li><li>学会使用依赖注入解耦代码</li><li>实现Coordinator模式管理应用导航</li><li>编写单元和UI测试保证代码质量</li></ul><p>本书适合已具备Swift和UIKit基础，希望进一步提升代码架构能力、掌握MVVM开发模式、并希望在iOS 18新环境下构建高质量纯代码应用的开发者。通过学习本书，你将能够独立完成从界面搭建到架构设计的全流程开发，具备构建企业级iOS应用的能力。</p>',7)]))}const V=t(o,[["render",r]]);export{c as __pageData,V as default};
